 function ordinal(n:number){return n===1?'ST':n===2?'ND':n===3?'RD':'TH'}
 function renderResult(){const r=game.result!;const got=r.awards.filter(Boolean).length;show(`<div class="screen"><div class="card"><div class="topline">${r.place===1?'CHAMPION!':'RACE COMPLETE'}</div><h2>${r.place===1?'Victory!':r.place===2?'So close!':'Good effort!'}</h2><p>${r.place===1?'The robot union has filed a complaint about that boot.':`${esc(game.player.name)} is mostly in one piece. Mostly.`}</p><div class="result-badges">${r.awards.map((ok,i)=>`<div class="result-badge"><strong>${ok?'🟡 +1':'○ 0'}</strong>${['Finish 1st','Spin goal','Jump height','Race distance'][i]}</div>`).join('')}</div><p>Spins: <b>${r.spins}</b> &nbsp; Max air: <b>${r.height}m</b></p><p>Chips earned: <span class="chip-count">${got}</span> &nbsp; Total: <span class="chip-count">${game.chips}</span></p><div class="button-row">${game.levelIndex+1<game.unlocked&&game.levelIndex+1<LEVELS.length?btn('NEXT LEVEL →','next','gold'):btn('RACE AGAIN','again','gold')}${btn('GARAGE & UPGRADES','upgrades','secondary')}${btn('MAIN MENU','menu','secondary')}</div></div></div>`);controls.classList.add('hidden');touchHint.classList.add('hidden');save()}
 function render(){if(game.screen==='race'){if(game.state==='result'){if(!resultShown){resultShown=true;renderResult()}}else if(game.frame%3===0)renderHud()}else if(game.screen==='result'&&game.result)renderResult()}
 ui.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!target)return;const action=target.dataset.action!;switch(action){case'menu':menu();break;case'howto':howto();break;case'start-tournament':levels('tournament');break;case'quick':levels('quick');break;case'upgrades':upgrades();break;case'settings':settings();break;case'level':selectedLevel=Number(target.dataset.level);levels(activeLevelMode);break;case'start-selected':startRace(selectedLevel,activeLevelMode==='quick'&&quickSolo,sessionPlayers);break;case'toggle-solo':quickSolo=!quickSolo;levels('quick');break;case'buy':{const k=target.dataset.stat as keyof Stats;const cost=upgradeCost(game.stats[k]);if(game.chips>=cost&&game.stats[k]<10){game.chips-=cost;game.stats[k]++;game.stats={...game.stats};save();upgrades()}break}case'bot-minus':game.settingsBot=Math.max(0,game.settingsBot-1);save();settings();break;case'bot-plus':game.settingsBot=Math.min(3,game.settingsBot+1);save();settings();break;case'sound':game.sound=!game.sound;save();settings();break;case'reset-confirm':confirmProgressReset();break;case'cancel-reset':settings();break;case'confirm-reset':game.chips=3;game.unlocked=1;game.cleared.clear();game.stats={...DEFAULT_STATS};selectedLevel=0;save();settings();break;case'resume':game.paused=false;renderHud();break;case'quit':menu();break;case'again':startRace(game.levelIndex,game.solo);break;case'next':startRace(Math.min(game.levelIndex+1,game.unlocked-1));break}}
